      final keys = SecureKeyCache(store);
      await keys.preload(['OPENAI_API_KEY']);
      expect(
        freshInstallProviderState(
          customProviders: const [],
          keys: keys,
          env: const {},
        ),
        isFalse,
      );
    });

    test('a saved custom provider is not fresh', () {
      expect(
        freshInstallProviderState(
          customProviders: [
