    final keys = items.map((i) => i.key).toList();
    expect(keys, contains('preset:copilot'));
    final copilot = items.firstWhere((i) => i.key == 'preset:copilot');
    expect(copilot.label, contains('Copilot'));

    io.sendLine('/exit');
    await run;
  });

