  /// no default model anymore, so the id comes from the endpoint's live
  /// /models (user picks) or a manual entry — never a hardcoded 'k3'.
  /// Null = cancelled.
  Future<String?> _kimiPickModel(
    ProviderSpec spec,
    String url,
    String? key,
  ) async {
