    io.sendLine('1'); // openai-like
    await waitForIt(() => io.out.toString().contains('base URL (empty ='));
    io.sendLine('https://proxy.example.com/v1');
    await waitForIt(() => io.out.toString().contains('provider name (empty ='));
    io.sendLine('work');
    await waitForIt(
